class BankAccount {
private:
    double balance;
public:
    BankAccount(double initial_bal) : balance(initial_bal) {}
    void deposit(double amount) { balance += amount; }
    double getBalance() const { return balance; }
};

topics.examples:
#include <iostream>

class Counter {
private:
    int count;
public:
    Counter() : count(0) {}
    void increment() { count++; }
    int get() const { return count; }
};

int main() {
    Counter c;
    c.increment();
    std::cout << "Count: " << c.get() << std::endl;
    return 0;
}

topics.syntax:
class Animal {
    void speak() {
        System.out.println("Animal sound");
    }
}

class Dog extends Animal {
    @Override
    void speak() {
        System.out.println("Woof!");
    }
}

topics.examples:
public class Main {
    public static void main(String[] args) {
        Animal myPet = new Dog();
        myPet.speak(); // Prints "Woof!" via polymorphism
    }
}

